def to_underscore(name):
    if isinstance(name, (int, float)):
        return str(int(name))

    result = []
    for i, char in enumerate(name):
        if char.isupper():
            if i > 0 and name[i-1].isalnum() and not name[i-1].isupper():
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)
